-- kazanimlar tablosunu KAZANIMLAR/*.xlsx listelerine göre yeniler (tek kaynak bu liste).
-- Üreten: scripts/kazanim_listesi_to_kazanim.py — elle düzenlemeyin, betiği yeniden çalıştırın.
-- 20260929_kazanimlar_2026_2027.sql çalıştırılmış olsun ya da olmasın bunu tek başına çalıştırabilirsiniz.
-- Geri almak için: 20261002_kazanimlar_liste_rollback.sql

BEGIN;

-- 1) Çalıştırma anındaki tablonun tam yedeği
CREATE TABLE IF NOT EXISTS public.kazanimlar_arsiv_20261002 AS TABLE public.kazanimlar;
ALTER TABLE public.kazanimlar_arsiv_20261002 ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS auth_select ON public.kazanimlar_arsiv_20261002;
CREATE POLICY auth_select ON public.kazanimlar_arsiv_20261002 FOR SELECT TO authenticated USING (true);

-- 2) Yeni kolonlar: sira (listedeki sıra), alt_kazanimlar (kod+metin listesi),
--    dersler.alt_kazanim_kodlari (o derste işaretlenen alt kazanımlar)
ALTER TABLE public.kazanimlar ADD COLUMN IF NOT EXISTS sira integer;
ALTER TABLE public.kazanimlar ADD COLUMN IF NOT EXISTS alt_kazanimlar jsonb;
ALTER TABLE public.dersler ADD COLUMN IF NOT EXISTS alt_kazanim_kodlari text[];

-- 3) Listenin kapsadığı ders/sınıf çiftlerini sil
DELETE FROM public.kazanimlar WHERE (ders, sinif) IN (
  ('Din Kültürü ve Ahlak Bilgisi', '5. Sınıf'),
  ('Din Kültürü ve Ahlak Bilgisi', '6. Sınıf'),
  ('Din Kültürü ve Ahlak Bilgisi', '7. Sınıf'),
  ('Din Kültürü ve Ahlak Bilgisi', '8. Sınıf'),
  ('Fen Bilimleri', '5. Sınıf'),
  ('Fen Bilimleri', '6. Sınıf'),
  ('Fen Bilimleri', '7. Sınıf'),
  ('Fen Bilimleri', '8. Sınıf'),
  ('Sosyal Bilgiler', '5. Sınıf'),
  ('Sosyal Bilgiler', '6. Sınıf'),
  ('Sosyal Bilgiler', '7. Sınıf'),
  ('T.C. İnkılap Tarihi ve Atatürkçülük', '8. Sınıf'),
  ('Türkçe', '5. Sınıf'),
  ('Türkçe', '6. Sınıf'),
  ('Türkçe', '7. Sınıf'),
  ('Türkçe', '8. Sınıf'),
  ('İlköğretim Matematik', '5. Sınıf'),
  ('İlköğretim Matematik', '6. Sınıf'),
  ('İlköğretim Matematik', '7. Sınıf'),
  ('İlköğretim Matematik', '8. Sınıf'),
  ('İngilizce', '5. Sınıf'),
  ('İngilizce', '6. Sınıf'),
  ('İngilizce', '7. Sınıf'),
  ('İngilizce', '8. Sınıf')
);

-- 4) Yeni satırlar

COMMIT;
