('5. Sınıf', 'Sayılar ve Nicelikler (1)', 'Sayılar ve Nicelikler (1)', 'M.5.1.1.', 'Altı basamaklı sayıları okuma ve yazmayı çok basamaklı sayılara genelleyebilme', 'İlköğretim Matematik', 1, '[{"kod": "M.5.1.1.A", "metin": "Günlük hayattaki farklı bağlamlardan yola çıkarak altıdan çok basamaklı sayılar hakkında bilgi toplar."}, {"kod": "M.5.1.1.B", "metin": "Sayıların bölükleri ile okunuşları arasındaki ortak özellikleri belirler."}, {"kod": "M.5.1.1.C", "metin": "Sayıların bölükleri ile okunuşları arasındaki örüntüler üzerinden basamak sayısı altıdan çok olan sayıların okunuş ve yazılışları hakkında önermelerde bulunur."}]'::jsonb),
('5. Sınıf', 'Sayılar ve Nicelikler (1)', 'Sayılar ve Nicelikler (1)', 'M.5.1.2.', 'Doğal sayılar ve işlemler içeren gerçek yaşam problemlerini çözebilme', 'İlköğretim Matematik', 2, '[{"kod": "M.5.1.2.A", "metin": "Problemin içerdiği sayı ve işlem bileşenlerini belirler."}, {"kod": "M.5.1.2.B", "metin": "Problemde verilenler ile istenenlerin gerektirdiği işlemler arasındaki ilişkiyi belirler."}, {"kod": "M.5.1.2.C", "metin": "Problem bağlamıyla ilişkili verilenleri uygun matematiksel temsillere dönüştürür."}, {"kod": "M.5.1.2.Ç", "metin": "Problemi matematiksel temsiller kullanarak kendi ifadeleri ile açıklar."}, {"kod": "M.5.1.2.D", "metin": "Problemin sonucuna ilişkin tahminde bulunur ve işlemleri gerçekleştirmek için stratejiler geliştirir."}, {"kod": "M.5.1.2.E", "metin": "Belirlenen strateji veya stratejileri çözüm için uygular."}, {"kod": "M.5.1.2.F", "metin": "Çözüm yollarını kontrol eder ve çözüme ulaştırmayan stratejiyi değiştirir."}, {"kod": "M.5.1.2.G", "metin": "Problemin çözümü için kullandığı veya geliştirdiği stratejileri gözden geçirerek kısa yolları değerlendirir."}, {"kod": "M.5.1.2.Ğ", "metin": "Kullandığı strateji veya stratejileri farklı problemlerin çözümlerine geneller."}, {"kod": "M.5.1.2.H", "metin": "Genellemenin geçerliliğini matematiksel örneklerle değerlendirir."}]'::jsonb),
('5. Sınıf', 'Sayılar ve Nicelikler (2)', 'Sayılar ve Nicelikler (2)', 'M.5.1.3.', 'Gerçek yaşam durumlarına karşılık gelen kesirleri farklı biçimlerde temsil edebilme', 'İlköğretim Matematik', 3, '[{"kod": "M.5.1.3.A", "metin": "Kesirlerin farklı gösterimlerinin (bileşik, tam sayılı, ondalık, yüzde) gerçek yaşam durumu içerisindeki kullanımını anlar."}, {"kod": "M.5.1.3.B", "metin": "Gerçek yaşam durumlarında karşılaşılan kesirlerin farklı gösterimlerini ilişkilendirmek için farklı modelleri (yüzlük kart, somut modeller, sayı doğrusu gibi) seçer."}, {"kod": "M.5.1.3.C", "metin": "Seçilen modelleri kullanır."}, {"kod": "M.5.1.3.Ç", "metin": "Kullanılan modelleri kesirlerin farklı gösterimleri ile yorumlar."}, {"kod": "M.5.1.3.D", "metin": "Benzer durumlarda kullanılabilecek farklı modelleri kullanışlılık açısından karşılaştırır."}, {"kod": "M.5.1.3.E", "metin": "Karşılaştırdığı modellerin kullanışlılığına ilişkin karar verir."}]'::jsonb),
('5. Sınıf', 'Sayılar ve Nicelikler (2)', 'Sayılar ve Nicelikler (2)', 'M.5.1.4.', 'Farklı gösterimlerle ifade edilen kesirlerin karşılaştırılmasına yönelik çıkarım yapabilme', 'İlköğretim Matematik', 4, '[{"kod": "M.5.1.4.A", "metin": "Farklı gösterimlerle ifade edilen kesirlerin karşılaştırılmasına yönelik varsayımda bulunur."}, {"kod": "M.5.1.4.B", "metin": "Varsayımındaki ilişkileri inceleyerek kesirlerin karşılaştırılmasına yönelik genellemeleri belirler."}, {"kod": "M.5.1.4.C", "metin": "Elde ettiği genellemelerin varsayımını karşılayıp karşılamadığını sayı doğrusu, şekil gibi temsiller üzerinde gösterir."}, {"kod": "M.5.1.4.Ç", "metin": "Varsayımı ile ilgili ulaştığı sonuca yönelik matematiksel önermeleri sözel ya da sembolik temsil ile sunar."}, {"kod": "M.5.1.4.D", "metin": "Sunduğu önermelerin tahmin etme becerisine katkısını gerekçelerle açıklar."}]'::jsonb),
