('6. Sınıf', 'Sayılar ve Nicelikler', 'Sayılar ve Nicelikler (1)', 'M.6.1.1.', 'Karşılaştığı problem durumlarında bir doğal sayının çarpan ve katlarına yönelik muhakeme yapabilme', 'İlköğretim Matematik', 1, '[{"kod": "M.6.1.1.A", "metin": "Karşılaştığı durumlarda bir doğal sayının çarpan ve katlarına yönelik varsayımlarda bulunur."}, {"kod": "M.6.1.1.B", "metin": "Varsayımına yönelik örnek durumların içerdiği ilişkileri inceleyerek bir doğal sayının çarpan ve katlarına ilişkin genellemeleri belirler."}, {"kod": "M.6.1.1.C", "metin": "Elde ettiği genellemelerin varsayımını karşılayıp karşılamadığını çeşitli modellerle gösterir."}, {"kod": "M.6.1.1.Ç", "metin": "Varsayımı ile ilgili ulaştığı sonuca yönelik doğrulayabileceği matematiksel bir önermeyi sözel ya da sembolik temsil ile sunar."}, {"kod": "M.6.1.1.D", "metin": "Farklı problemlerin pratik yoldan çözümüne yönelik oluşturduğu önermenin gerekçelerini sunar."}, {"kod": "M.6.1.1.E", "metin": "Önermenin geçerliliğini destekleyen kapsayıcı örnekler verir."}, {"kod": "M.6.1.1.F", "metin": "İşe koştuğu doğrulamanın benzer önermelere uygulanıp uygulanamayaca ğını değerlendirir."}]'::jsonb),
('6. Sınıf', 'Sayılar ve Nicelikler', 'Sayılar ve Nicelikler (1)', 'M.6.1.2.', 'Bir doğal sayının 2, 3, 4, 5, 6, 9 ve 10 ile tam bölünebilme kriterlerine ilişkin çıkarım yapabilme', 'İlköğretim Matematik', 2, '[{"kod": "M.6.1.2.A", "metin": "Bir doğal sayının katlarını veya basamak değerlerini dikkate alarak 2, 3, 4, 5, 6, 9 ve 10''a tam bölünebilme kriterleri ile ilgili varsayımlarda bulunur."}, {"kod": "M.6.1.2.B", "metin": "2, 3, 4, 5, 6, 9 ve 10''un katlarını ve basamak değerlerini inceleyerek genellemeleri belirler."}, {"kod": "M.6.1.2.C", "metin": "Elde ettiği genellemelerin, varsayımını karşılayıp karşılamadığını örnekler ile sınar."}, {"kod": "M.6.1.2.Ç", "metin": "Bir doğal sayının 2, 3, 4, 5, 6, 9 ve 10 ile tam bölünebilmesindeki kriterlere ilişkin önerme sunar."}, {"kod": "M.6.1.2.D", "metin": "Bir doğal sayının 2, 3, 4, 5, 6, 9 ve 10 ile tam bölünebilmesindeki kriterlerin farklı durumlarda kullanışlılığını değerlendirir."}]'::jsonb),
('6. Sınıf', 'Sayılar ve Nicelikler', 'Sayılar ve Nicelikler (1)', 'M.6.1.3.', 'Bir doğal sayının asal olma durumunu ve asal çarpanlarını çözümleyebilme', 'İlköğretim Matematik', 3, '[{"kod": "M.6.1.3.A", "metin": "Bir doğal sayının asal olup olmadığını ve asal çarpanlarını belirler."}, {"kod": "M.6.1.3.B", "metin": "Asal sayıların özelliklerini ve bir doğal sayı ile asal çarpanları arasındaki ilişkileri belirler."}]'::jsonb),
('6. Sınıf', 'Sayılar ve Nicelikler', 'Sayılar ve Nicelikler (1)', 'M.6.1.4.', 'Günlük hayat problemleri ya da matematiksel durumlar üzerinden ortak kat ve ortak böleni yorumlayabilme', 'İlköğretim Matematik', 4, '[{"kod": "M.6.1.4.A", "metin": "Problemlerde ya da matematiksel durumlarda verilen iki sayının ortak katlarını ve ortak bölenlerini inceler."}, {"kod": "M.6.1.4.B", "metin": "İncelediği ortak kat veya ortak bölen ilişkilerini çizim, tablo ve sayı doğrusu gibi matematiksel temsillerle ifade eder."}, {"kod": "M.6.1.4.C", "metin": "İki sayının ortak katlarını ve ortak bölenlerini kendi ifadelerini kullanarak açıklar."}]'::jsonb),
('6. Sınıf', 'Sayılar ve Nicelikler (2)', 'Sayılar ve Nicelikler (2)', 'M.6.1.5.', 'Gerçek yaşam durumlarında ondalık gösterimlerin basamak değerlerini kesir lerden yararlanarak yorumlayabilme', 'İlköğretim Matematik', 5, '[{"kod": "M.6.1.5.A", "metin": "Ondalık gösterimlerin basamak değerlerini inceler."}, {"kod": "M.6.1.5.B", "metin": "Ondalık gösterimlerin basamak değerlerini paydası 10, 100 ve 1000 olan kesirlerin toplamlarını kullanarak yeniden ifade eder."}, {"kod": "M.6.1.5.C", "metin": "Ondalık gösterimlerin basamak değerlerini kendi cümleleriyle açıklar."}]'::jsonb),
